import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../../../shared/widgets/state_views.dart';
import '../controllers/business_providers.dart';
import '../widgets/business_card.dart';
class ExploreScreen extends ConsumerWidget{ const ExploreScreen({super.key}); @override Widget build(BuildContext context,WidgetRef ref){ final cats=ref.watch(businessCategoriesProvider); final list=ref.watch(businessListProvider); return Scaffold(appBar:AppBar(title:const Text('Explore')),body:SafeArea(child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,8,16,8),child:TextField(textInputAction:TextInputAction.search,decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Search business'),onChanged:(v)=>ref.read(searchQueryProvider.notifier).state=v.trim())),SizedBox(height:48,child:cats.when(data:(items)=>ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:16),children:[_Filter(label:'All',selected:ref.watch(selectedCategoryProvider)==null,onTap:()=>ref.read(selectedCategoryProvider.notifier).state=null),...items.map((c)=>_Filter(label:c.name,selected:ref.watch(selectedCategoryProvider)==c.slug,onTap:()=>ref.read(selectedCategoryProvider.notifier).state=c.slug))]),loading:()=>const LoadingStateView(),error:(_,_)=>const SizedBox.shrink())),Padding(padding:const EdgeInsets.fromLTRB(16,8,16,8),child:SegmentedButton<String?>(segments:const [ButtonSegment(value:null,label:Text('Default'),icon:Icon(Icons.sort)),ButtonSegment(value:'shortest',label:Text('Shortest'),icon:Icon(Icons.trending_down)),ButtonSegment(value:'longest',label:Text('Longest'),icon:Icon(Icons.trending_up))],selected:{ref.watch(queueLengthFilterProvider)},onSelectionChanged:(v)=>ref.read(queueLengthFilterProvider.notifier).state=v.first)),Expanded(child:list.when(data:(items)=>items.isEmpty?const EmptyStateView(title:'No results found',message:'Try another keyword or category.'):RefreshIndicator(onRefresh:()async=>ref.invalidate(businessListProvider),child:ListView.builder(padding:const EdgeInsets.fromLTRB(16,0,16,16),itemCount:items.length,itemBuilder:(context,i)=>BusinessCard(business:items[i],onTap:()=>context.go('/businesses/${items[i].id}')))),loading:()=>const LoadingStateView(),error:(_,_)=>ErrorStateView(message:'Unable to load businesses.',onRetry:()=>ref.invalidate(businessListProvider))))])));}}
class _Filter extends StatelessWidget{ const _Filter({required this.label,required this.selected,required this.onTap}); final String label; final bool selected; final VoidCallback onTap; @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(right:8),child:FilterChip(label:Text(label),selected:selected,onSelected:(_)=>onTap()));}